function parcelTranslate(value) {
  let result = value;
  for (const [source, target] of Object.entries(parcelTranslations).sort((a,b) => b[0].length-a[0].length)) {
    if (result.trim() === source) return result.replace(source, target);
  }
  result = result.replace(/(\d+) Registrierung(?:en)? warten auf Freigabe\./g, (_, n) => `${n} registration${n === '1' ? '' : 's'} awaiting approval.`);
  result = result.replace(/(\d+) Treffer/g, '$1 results');
  result = result.replace(/(\d+) Artikel aus der XLS-Datei übernommen/g, '$1 items imported from the XLS file');
  result = result.replace(/(#\d+ · \d+) Artikel/g, '$1 items');
  result = result.replace(/Angemeldet als (.+)/g, 'Signed in as $1');
  result = result.replace(/Benutzername:\s*/g, 'Username: ');
  result = result.replace(/^Artikel \*$/, 'Item *');
  result = result.replace(/Import fehlgeschlagen:/g, 'Import failed:');
  result = result.replace(/Gruppe „(.+?)“ kann noch nicht gelöscht werden: erst (\d+) Mitarbeiter und (\d+) Bestellungen anderen Gruppen zuweisen\./g, 'Group “$1” cannot be deleted yet. Reassign $2 employees and $3 orders first.');
  result = result.replace(/Gruppe „(.+?)“ gelöscht/g, 'Group “$1” deleted');
  result = result.replace(/Artikel hinzugefügt:/g, 'Item added:');
  result = result.replace(/Artikel entfernt:/g, 'Item removed:');
  result = result.replace(/(\d+) Artikel aus Mouser-XLS importiert/g, '$1 items imported from Mouser XLS');
  result = result.replace(/Status: (Warenkorb|Warenkorb fertig|Bestellt|Unterwegs|Angekommen|Abgeholt) → (Warenkorb|Warenkorb fertig|Bestellt|Unterwegs|Angekommen|Abgeholt)/g, (_,a,b) => `Status: ${parcelTranslations[a]} → ${parcelTranslations[b]}`);
  result = result.replace(/Bestellung angelegt \((Warenkorb|Warenkorb fertig|Bestellt|Unterwegs|Angekommen|Abgeholt)\)/g, (_,s) => `Order created (${parcelTranslations[s]})`);
  return result;
}

document.addEventListener('DOMContentLoaded', () => {
  let language = 'en';
  try { language = localStorage.getItem('parcel-language') === 'de' ? 'de' : 'en'; } catch (_) {}
  window.parcelLanguage = language;
  const toggle = document.getElementById('language-toggle');
  const themeToggle = document.getElementById('theme-toggle');
  const themeMenu = document.getElementById('theme-menu');
  const availableThemes = ['sage','ocean','lavender','dark'];
  const themeColor = document.querySelector('meta[name="theme-color"]');
  let theme = 'sage';
  try {
    const savedTheme = localStorage.getItem('parcel-theme');
    if (availableThemes.includes(savedTheme)) theme = savedTheme;
  } catch (_) {}
  const applyTheme = selectedTheme => {
    theme = availableThemes.includes(selectedTheme) ? selectedTheme : 'sage';
    document.documentElement.dataset.theme = theme;
    if (themeColor) themeColor.content = getComputedStyle(document.documentElement).getPropertyValue('--page-bg').trim();
    document.querySelectorAll('[data-theme-choice]').forEach(option => {
      const active = option.dataset.themeChoice === theme;
      option.classList.toggle('active', active);
      option.setAttribute('aria-pressed', String(active));
    });
  };
  const closeThemeMenu = () => {
    if (!themeMenu || !themeToggle) return;
    themeMenu.hidden = true;
    themeToggle.setAttribute('aria-expanded', 'false');
  };
  applyTheme(theme);
  if (themeToggle && themeMenu) {
    themeToggle.addEventListener('click', () => {
      const willOpen = themeMenu.hidden;
      themeMenu.hidden = !willOpen;
      themeToggle.setAttribute('aria-expanded', String(willOpen));
      if (willOpen) {
        const rect = themeToggle.getBoundingClientRect();
        themeMenu.style.top = `${Math.min(rect.bottom + 8, window.innerHeight - 210)}px`;
        themeMenu.style.right = `${Math.max(12, window.innerWidth - rect.right)}px`;
      }
    });
    themeMenu.querySelectorAll('[data-theme-choice]').forEach(option => {
      option.addEventListener('click', () => {
        applyTheme(option.dataset.themeChoice);
        try { localStorage.setItem('parcel-theme', theme); } catch (_) {}
        closeThemeMenu();
      });
    });
    document.addEventListener('click', event => {
      if (!themeMenu.contains(event.target) && !themeToggle.contains(event.target)) closeThemeMenu();
    });
    document.addEventListener('keydown', event => {
      if (event.key === 'Escape') closeThemeMenu();
    });
  }
  const translatePage = () => {
    if (language === 'en') {
      const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
      const nodes = [];
      while (walker.nextNode()) nodes.push(walker.currentNode);
      for (const node of nodes) node.nodeValue = parcelTranslate(node.nodeValue);
      for (const element of document.querySelectorAll('[placeholder],[title],[aria-label],[onclick]')) {
        for (const attr of ['placeholder','title','aria-label','onclick']) {
          if (element.hasAttribute(attr)) {
            const value = element.getAttribute(attr);
            element.setAttribute(attr, attr === 'onclick' ? value.replace(/Bestellung und Verlauf endgültig löschen\?/g,'Permanently delete this order and its history?').replace(/Artikel löschen\?/g,'Delete item?').replace(/Gruppe löschen\? Nur leere Gruppen können gelöscht werden\./g,'Delete group? Only empty groups can be deleted.') : parcelTranslate(value));
          }
        }
      }
      document.querySelectorAll('h1').forEach(heading => { if (heading.textContent.trim() === 'Employee') heading.textContent = 'Employees'; });
      document.querySelectorAll('th').forEach(heading => { if (heading.textContent.trim() === 'Employee') heading.textContent = 'Employees'; });
      document.documentElement.lang = 'en';
      document.title = 'Order management · Parcel';
    } else {
      document.documentElement.lang = 'de';
      document.title = 'Paketverwaltung · Parcel';
    }
    if (toggle) {
      toggle.textContent = language === 'de' ? 'EN' : 'DE';
      toggle.title = language === 'de' ? 'Switch to English' : 'Auf Deutsch umstellen';
      toggle.setAttribute('aria-label', toggle.title);
    }
  };
  translatePage();
  for (const element of document.querySelectorAll('time.local-time[data-utc]')) {
    const match = element.dataset.utc.match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}) UTC$/);
    if (!match) continue;
    const [,year,month,day,hour,minute] = match;
    const date = new Date(Date.UTC(Number(year),Number(month)-1,Number(day),Number(hour),Number(minute)));
    element.dateTime = date.toISOString();
    element.textContent = new Intl.DateTimeFormat(language === 'en' ? 'en-GB' : 'de-DE',{dateStyle:'medium',timeStyle:'short'}).format(date);
  }
  const currentMonth = new Date();
  const currentMonthIndex = currentMonth.getFullYear() * 12 + currentMonth.getMonth();
  for (const row of document.querySelectorAll('.order-row[data-created-at]')) {
    const match = row.dataset.createdAt.match(/^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}) UTC$/);
    if (!match) continue;
    const [,year,month,day,hour,minute] = match;
    const createdAt = new Date(Date.UTC(Number(year),Number(month)-1,Number(day),Number(hour),Number(minute)));
    const monthIndex = createdAt.getFullYear() * 12 + createdAt.getMonth();
    if (Math.abs(currentMonthIndex - monthIndex) % 2 === 0) row.classList.add('month-tinted');
  }
  if (toggle) toggle.addEventListener('click', () => {
    language = language === 'de' ? 'en' : 'de';
    try { localStorage.setItem('parcel-language', language); } catch (_) {}
    window.location.reload();
  });
});

document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('.mouser-file-input').forEach(input => {
    input.addEventListener('change', () => {
      const label = input.closest('.mouser-file-picker');
      const name = label && label.querySelector('.mouser-file-name');
      if (name) name.textContent = input.files.length ? input.files[0].name : (window.parcelLanguage === 'en' ? 'No file selected' : 'Keine Datei ausgewählt');
    });
  });
});

document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('[data-pickup-select]').forEach(select => {
    const customInput = document.getElementById(select.dataset.pickupSelect);
    if (!customInput) return;
    const sync = () => {
      const isCustom = select.value === '__custom__';
      const customField = customInput.closest('.pickup-custom-field');
      if (customField) customField.hidden = !isCustom;
      customInput.hidden = !isCustom;
      if (!isCustom) customInput.value = '';
    };
    select.addEventListener('change', sync);
    sync();
  });
});

document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('[data-carrier-select]').forEach(select => {
    const customInput = document.getElementById(select.dataset.carrierSelect);
    if (!customInput) return;
    const customField = customInput.closest('[data-carrier-field-wrapper]');
    const sync = () => {
      const isCustom = select.value === '__custom__';
      if (customField) customField.hidden = !isCustom;
      customInput.hidden = !isCustom;
      if (!isCustom) customInput.value = '';
    };
    select.addEventListener('change', sync);
    sync();
  });
});

document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('[data-clear-pickup]').forEach(button => {
    button.addEventListener('click', () => {
      const form = button.closest('form');
      const clearFlag = form && form.querySelector('input[name="clear_pickup"]');
      const status = form && form.querySelector('select[name="status"]');
      const fields = form && [...form.querySelectorAll('[data-pickup-field]')];
      if (!clearFlag || !status || !fields) return;
      const message = window.parcelLanguage === 'en'
        ? 'Remove the pickup details and reset the order to Arrived?'
        : 'Abholdaten entfernen und den Status auf Angekommen zurücksetzen?';
      if (!window.confirm(message)) return;
      clearFlag.value = '1';
      status.value = 'Angekommen';
      fields.forEach(field => { field.value = ''; field.required = false; if (field.matches('input')) field.hidden = true; });
    });
  });
});

document.addEventListener('DOMContentLoaded', () => {
  document.querySelectorAll('.manual-status form[data-pickup-dialog]').forEach(form => {
    form.addEventListener('submit', event => {
      const status = form.querySelector('select[name="status"]');
      if (!status || status.value !== 'Abgeholt') return;
      const dialog = document.getElementById(form.dataset.pickupDialog);
      if (!dialog) return;
      event.preventDefault();
      dialog.showModal();
    });
  });
});

document.addEventListener('DOMContentLoaded', () => {
  const search = document.getElementById('order-search');
  const status = document.getElementById('status-filter');
  const year = document.getElementById('year-filter');
  const rows = [...document.querySelectorAll('.order-row')];
  const empty = document.getElementById('empty-state');
  const count = document.getElementById('results-count');
  if (!search || !status || !year || !empty || !count) return;

  const cards = [...document.querySelectorAll('.stat[data-status]')];
  const filter = () => {
    const query = search.value.trim().toLocaleLowerCase('de');
    const selectedStatus = status.value;
    const selectedYear = year.value;
    let visible = 0;
    const statusCounts = new Map();

    for (const row of rows) {
      const baseMatches = (selectedYear === 'all' || row.dataset.year === selectedYear)
        && (!query || row.dataset.search.includes(query));
      if (baseMatches) statusCounts.set(row.dataset.status, (statusCounts.get(row.dataset.status) || 0) + 1);
      const matches = baseMatches && (!selectedStatus || row.dataset.status === selectedStatus);
      row.hidden = !matches;
      if (matches) visible += 1;
    }

    empty.hidden = visible > 0;
    count.textContent = `${visible} ${window.parcelLanguage === 'en' ? 'results' : 'Treffer'}`;
    for (const card of cards) {
      card.classList.toggle('active', card.dataset.status === selectedStatus);
      const cardCount = card.querySelector('.stat-number');
      if (cardCount) cardCount.textContent = statusCounts.get(card.dataset.status) || 0;
    }

    const url = new URL(window.location.href);
    if (query) url.searchParams.set('q', search.value.trim());
    else url.searchParams.delete('q');
    if (selectedStatus) url.searchParams.set('status', selectedStatus);
    else url.searchParams.delete('status');
    url.searchParams.set('year', selectedYear);
    window.history.replaceState({}, '', url);
  };

  search.addEventListener('input', filter);
  status.addEventListener('change', filter);
  year.addEventListener('change', filter);
  for (const card of cards) {
    card.addEventListener('click', (event) => {
      event.preventDefault();
      status.value = status.value === card.dataset.status ? '' : card.dataset.status;
      filter();
    });
  }
  filter();
});


document.addEventListener('DOMContentLoaded', () => {
  const password = document.getElementById('start-password');
  const error = document.getElementById('start-password-error');
  if (!password || !error) return;

  const validateAfterBlur = () => {
    const invalid = password.value.length > 0 && password.value.length < 12;
    error.hidden = !invalid;
    password.setAttribute('aria-invalid', invalid ? 'true' : 'false');
  };
  password.addEventListener('blur', validateAfterBlur);
  password.addEventListener('input', () => {
    if (!error.hidden && password.value.length >= 12) validateAfterBlur();
  });
});
